# Comprueba que los pesos suman 1. Es una función interna: no se exporta.
#' @noRd
comprueba_pesos <- function(pesos) {
  if (abs(sum(pesos) - 1) > 1e-8) {
    stop("los pesos suman ", sum(pesos), ", no 1")
  }
  invisible(TRUE)
}

